import React, { useState } from "react";
import {
  AppBar,
  Toolbar,
  Typography,
  Box,
  Button,
  Grid,
  Card,
  CardContent,
  CardMedia,
  IconButton,
  Badge,
  Avatar,
  Drawer,
  List,
  ListItem,
  Divider,
  TextField,
  InputAdornment,
  Chip,
  Paper,
} from "@mui/material";

import {
  Restaurant as RestaurantIcon,
  ShoppingCart as CartIcon,
  Search as SearchIcon,
  Logout as LogoutIcon,
  Home as HomeIcon,
  ReceiptLong as OrdersIcon,
  Person as PersonIcon,
  Add as AddIcon,
  Remove as RemoveIcon,
  Close as CloseIcon,
} from "@mui/icons-material";

/* =========================================================
   MENU DATA
========================================================= */

const menuItems = [
  {
    id: 1,
    name: "Masala Dosa",
    category: "Breakfast",
    price: 80,
    image:
      "https://images.unsplash.com/photo-1631452180519-c014fe946bc7?w=600",
    description:
      "Crispy South Indian dosa served with chutney and sambar.",
  },
  {
    id: 2,
    name: "Biryani",
    category: "Lunch",
    price: 180,
    image:
      "https://www.awesomecuisine.com/wp-content/uploads/2008/03/Vegetable-Biryani.jpg",
    description:
      "Aromatic rice cooked with vegetables and traditional spices.",
  },
  {
    id: 3,
    name: "Butter Chicken",
    category: "Lunch",
    price: 220,
    image:
      "https://images.unsplash.com/photo-1565557623262-b51c2513a641?w=600",
    description:
      "Creamy and flavorful butter chicken prepared with Indian spices.",
  },
  {
    id: 4,
    name: "Paneer Tikka",
    category: "Dinner",
    price: 160,
    image:
      "https://images.unsplash.com/photo-1599487488170-d11ec9c172f0?w=600",
    description:
      "Grilled paneer cubes marinated in aromatic spices.",
  },
  {
    id: 5,
    name: "Samosa",
    category: "Snacks",
    price: 40,
    image:
      "https://images.unsplash.com/photo-1601050690597-df0568f70950?w=600",
    description:
      "Crispy samosa filled with spiced potato.",
  },
  {
    id: 6,
    name: "Chai",
    category: "Beverages",
    price: 20,
    image:
      "https://images.unsplash.com/photo-1571934811356-5cc061b6821f?w=600",
    description:
      "Freshly prepared Indian tea.",
  },
  {
    id: 7,
    name: "Burger",
    category: "Snacks",
    price: 150,
    image:
      "https://images.unsplash.com/photo-1568901346375-23c9450c58cd?w=600",
    description:
      "Fresh burger with crispy vegetables and delicious sauce.",
  },
  {
    id: 8,
    name: "Noodles",
    category: "Lunch",
    price: 120,
    image:
      "https://shwetainthekitchen.com/wp-content/uploads/2023/03/vegetable-noodles.jpg",
    description:
      "Stir-fried noodles with fresh vegetables.",
  },
];

/* =========================================================
   USER DASHBOARD
========================================================= */

const UserDashboard = ({ user, onLogout }) => {
  const [activePage, setActivePage] =
    useState("Home");

  const [search, setSearch] =
    useState("");

  const [category, setCategory] =
    useState("All");

  const [cart, setCart] = useState([]);

  const [cartOpen, setCartOpen] =
    useState(false);

  const categories = [
    "All",
    "Breakfast",
    "Lunch",
    "Dinner",
    "Snacks",
    "Beverages",
  ];

  /* =======================================================
     ADD TO CART
  ======================================================= */

  const addToCart = (item) => {
    setCart((previousCart) => {
      const existingItem =
        previousCart.find(
          (cartItem) =>
            cartItem.id === item.id
        );

      if (existingItem) {
        return previousCart.map(
          (cartItem) =>
            cartItem.id === item.id
              ? {
                  ...cartItem,
                  quantity:
                    cartItem.quantity + 1,
                }
              : cartItem
        );
      }

      return [
        ...previousCart,
        {
          ...item,
          quantity: 1,
        },
      ];
    });
  };

  /* =======================================================
     CHANGE CART QUANTITY
  ======================================================= */

  const changeQuantity = (
    id,
    change
  ) => {
    setCart((previousCart) =>
      previousCart
        .map((item) =>
          item.id === id
            ? {
                ...item,
                quantity:
                  item.quantity + change,
              }
            : item
        )
        .filter(
          (item) => item.quantity > 0
        )
    );
  };

  /* =======================================================
     CART TOTAL
  ======================================================= */

  const cartCount = cart.reduce(
    (total, item) =>
      total + item.quantity,
    0
  );

  const cartTotal = cart.reduce(
    (total, item) =>
      total +
      item.price * item.quantity,
    0
  );

  /* =======================================================
     FILTER MENU
  ======================================================= */

  const filteredItems =
    menuItems.filter((item) => {
      const matchesSearch =
        item.name
          .toLowerCase()
          .includes(
            search.toLowerCase()
          );

      const matchesCategory =
        category === "All" ||
        item.category === category;

      return (
        matchesSearch &&
        matchesCategory
      );
    });

  /* =======================================================
     HOME PAGE
  ======================================================= */

  const renderHome = () => (
    <>
      {/* Welcome Banner */}

      <Paper
        sx={{
          p: {
            xs: 3,
            md: 4,
          },
          mb: 3,
          borderRadius: 3,
          background:
            "linear-gradient(135deg, #2E7D32, #4CAF50)",
          color: "white",
        }}
      >
        <Typography
          variant="h4"
          sx={{
            fontWeight: 800,
          }}
        >
          Welcome, {user.name}
        </Typography>

        <Typography
          sx={{
            mt: 1,
            opacity: 0.9,
          }}
        >
          What would you like to eat
          today?
        </Typography>
      </Paper>

      {/* Search */}

      <TextField
        fullWidth
        value={search}
        onChange={(e) =>
          setSearch(e.target.value)
        }
        placeholder="Search food..."
        sx={{
          mb: 3,
          backgroundColor: "white",
          borderRadius: 2,
        }}
        InputProps={{
          startAdornment: (
            <InputAdornment position="start">
              <SearchIcon />
            </InputAdornment>
          ),
        }}
      />

      {/* Categories */}

      <Box
        sx={{
          display: "flex",
          gap: 1,
          overflowX: "auto",
          pb: 2,
          mb: 2,
        }}
      >
        {categories.map(
          (itemCategory) => (
            <Chip
              key={itemCategory}
              label={itemCategory}
              onClick={() =>
                setCategory(
                  itemCategory
                )
              }
              color={
                category ===
                itemCategory
                  ? "primary"
                  : "default"
              }
              sx={{
                fontWeight: 600,
                px: 1,
              }}
            />
          )
        )}
      </Box>

      {/* Food Cards */}

      <Grid container spacing={3}>
        {filteredItems.map((item) => (
          <Grid
            item
            xs={12}
            sm={6}
            md={4}
            lg={3}
            key={item.id}
          >
            <Card
              sx={{
                height: "100%",
                borderRadius: 3,
                overflow: "hidden",
                transition:
                  "0.3s",
                "&:hover": {
                  transform:
                    "translateY(-5px)",
                  boxShadow:
                    "0 10px 25px rgba(0,0,0,0.15)",
                },
              }}
            >
              <CardMedia
                component="img"
                height="180"
                image={item.image}
                alt={item.name}
              />

              <CardContent>
                <Box
                  sx={{
                    display: "flex",
                    justifyContent:
                      "space-between",
                    alignItems:
                      "flex-start",
                    gap: 1,
                  }}
                >
                  <Typography
                    variant="h6"
                    sx={{
                      fontWeight: 700,
                    }}
                  >
                    {item.name}
                  </Typography>

                  <Chip
                    label={
                      item.category
                    }
                    size="small"
                    color="success"
                  />
                </Box>

                <Typography
                  variant="body2"
                  color="text.secondary"
                  sx={{
                    mt: 1,
                    minHeight: 40,
                  }}
                >
                  {item.description}
                </Typography>

                <Box
                  sx={{
                    display: "flex",
                    justifyContent:
                      "space-between",
                    alignItems:
                      "center",
                    mt: 2,
                  }}
                >
                  <Typography
                    variant="h6"
                    sx={{
                      color: "#2E7D32",
                      fontWeight: 800,
                    }}
                  >
                    ₹{item.price}
                  </Typography>

                  <Button
                    variant="contained"
                    startIcon={
                      <AddIcon />
                    }
                    onClick={() =>
                      addToCart(item)
                    }
                    sx={{
                      borderRadius: 2,
                      textTransform:
                        "none",
                      fontWeight: 700,
                    }}
                  >
                    Add
                  </Button>
                </Box>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      {filteredItems.length === 0 && (
        <Paper
          sx={{
            p: 5,
            textAlign: "center",
            borderRadius: 3,
          }}
        >
          <Typography
            variant="h6"
            color="text.secondary"
          >
            No food items found.
          </Typography>
        </Paper>
      )}
    </>
  );

  /* =======================================================
     ORDERS PAGE
  ======================================================= */

  const renderOrders = () => (
    <Paper
      sx={{
        p: 4,
        borderRadius: 3,
      }}
    >
      <Typography
        variant="h4"
        sx={{
          fontWeight: 800,
          color: "#2E7D32",
        }}
      >
        My Orders
      </Typography>

      <Divider sx={{ my: 2 }} />

      <Box
        sx={{
          textAlign: "center",
          py: 6,
        }}
      >
        <OrdersIcon
          sx={{
            fontSize: 60,
            color: "#BDBDBD",
          }}
        />

        <Typography
          variant="h6"
          color="text.secondary"
          sx={{ mt: 1 }}
        >
          No orders yet
        </Typography>

        <Typography
          color="text.secondary"
          sx={{ mt: 1 }}
        >
          Your placed orders will
          appear here.
        </Typography>
      </Box>
    </Paper>
  );

  /* =======================================================
     PROFILE PAGE
  ======================================================= */

  const renderProfile = () => (
    <Paper
      sx={{
        p: 4,
        borderRadius: 3,
      }}
    >
      <Box
        sx={{
          display: "flex",
          alignItems: "center",
          gap: 2,
          mb: 3,
        }}
      >
        <Avatar
          sx={{
            width: 70,
            height: 70,
            bgcolor: "#2E7D32",
            fontSize: 30,
          }}
        >
          {user.name
            ? user.name
                .charAt(0)
                .toUpperCase()
            : "U"}
        </Avatar>

        <Box>
          <Typography
            variant="h5"
            sx={{ fontWeight: 800 }}
          >
            {user.name}
          </Typography>

          <Typography color="text.secondary">
            User Account
          </Typography>
        </Box>
      </Box>

      <Divider sx={{ mb: 3 }} />

      <Typography
        variant="body1"
        sx={{ mb: 2 }}
      >
        <strong>Mobile:</strong>{" "}
        {user.mobile}
      </Typography>

      <Typography variant="body1">
        <strong>Role:</strong>{" "}
        {user.role}
      </Typography>
    </Paper>
  );

  /* =======================================================
     CART DRAWER
  ======================================================= */

  const cartDrawer = (
    <Box
      sx={{
        width: {
          xs: 320,
          sm: 400,
        },
        p: 3,
      }}
    >
      <Box
        sx={{
          display: "flex",
          justifyContent:
            "space-between",
          alignItems: "center",
        }}
      >
        <Typography
          variant="h5"
          sx={{ fontWeight: 800 }}
        >
          Your Cart
        </Typography>

        <IconButton
          onClick={() =>
            setCartOpen(false)
          }
        >
          <CloseIcon />
        </IconButton>
      </Box>

      <Divider sx={{ my: 2 }} />

      {cart.length === 0 ? (
        <Box
          sx={{
            textAlign: "center",
            py: 6,
          }}
        >
          <CartIcon
            sx={{
              fontSize: 60,
              color: "#BDBDBD",
            }}
          />

          <Typography
            color="text.secondary"
            sx={{ mt: 1 }}
          >
            Your cart is empty.
          </Typography>
        </Box>
      ) : (
        <>
          {cart.map((item) => (
            <Box
              key={item.id}
              sx={{
                display: "flex",
                gap: 2,
                mb: 2,
                alignItems: "center",
              }}
            >
              <Box
                component="img"
                src={item.image}
                alt={item.name}
                sx={{
                  width: 65,
                  height: 65,
                  objectFit: "cover",
                  borderRadius: 2,
                }}
              />

              <Box sx={{ flexGrow: 1 }}>
                <Typography
                  fontWeight={700}
                >
                  {item.name}
                </Typography>

                <Typography
                  color="primary"
                  fontWeight={700}
                >
                  ₹{item.price}
                </Typography>

                <Box
                  sx={{
                    display: "flex",
                    alignItems:
                      "center",
                    gap: 1,
                    mt: 0.5,
                  }}
                >
                  <IconButton
                    size="small"
                    onClick={() =>
                      changeQuantity(
                        item.id,
                        -1
                      )
                    }
                  >
                    <RemoveIcon fontSize="small" />
                  </IconButton>

                  <Typography fontWeight={700}>
                    {item.quantity}
                  </Typography>

                  <IconButton
                    size="small"
                    onClick={() =>
                      changeQuantity(
                        item.id,
                        1
                      )
                    }
                  >
                    <AddIcon fontSize="small" />
                  </IconButton>
                </Box>
              </Box>
            </Box>
          ))}

          <Divider sx={{ my: 2 }} />

          <Box
            sx={{
              display: "flex",
              justifyContent:
                "space-between",
            }}
          >
            <Typography
              variant="h6"
              fontWeight={800}
            >
              Total
            </Typography>

            <Typography
              variant="h6"
              fontWeight={800}
              color="primary"
            >
              ₹{cartTotal}
            </Typography>
          </Box>

          <Button
            fullWidth
            variant="contained"
            size="large"
            sx={{
              mt: 3,
              borderRadius: 2,
              fontWeight: 700,
            }}
            onClick={() => {
              alert(
                "Checkout will be connected to the backend next."
              );
            }}
          >
            Place Order
          </Button>
        </>
      )}
    </Box>
  );

  /* =======================================================
     MAIN UI
  ======================================================= */

  return (
    <Box
      sx={{
        minHeight: "100vh",
        backgroundColor: "#F5F7F5",
      }}
    >
      {/* HEADER */}

      <AppBar
        position="sticky"
        sx={{
          background:
            "linear-gradient(135deg, #2E7D32, #4CAF50)",
        }}
      >
        <Toolbar>
          <RestaurantIcon
            sx={{ mr: 1.5 }}
          />

          <Typography
            variant="h6"
            sx={{
              fontWeight: 800,
              flexGrow: 1,
            }}
          >
            CanteenPro
          </Typography>

          <IconButton
            color="inherit"
            onClick={() =>
              setCartOpen(true)
            }
          >
            <Badge
              badgeContent={cartCount}
              color="error"
            >
              <CartIcon />
            </Badge>
          </IconButton>

          <Button
            color="inherit"
            startIcon={<LogoutIcon />}
            onClick={onLogout}
            sx={{
              ml: 1,
              textTransform: "none",
              fontWeight: 700,
            }}
          >
            Logout
          </Button>
        </Toolbar>
      </AppBar>

      {/* NAVIGATION */}

      <Paper
        square
        elevation={0}
        sx={{
          borderBottom:
            "1px solid #E0E0E0",
          position: "sticky",
          top: 64,
          zIndex: 10,
        }}
      >
        <Box
          sx={{
            display: "flex",
            justifyContent:
              "center",
            gap: 1,
            p: 1,
            overflowX: "auto",
          }}
        >
          <Button
            startIcon={<HomeIcon />}
            onClick={() =>
              setActivePage("Home")
            }
            variant={
              activePage === "Home"
                ? "contained"
                : "text"
            }
            sx={{
              textTransform: "none",
              fontWeight: 700,
            }}
          >
            Home
          </Button>

          <Button
            startIcon={<OrdersIcon />}
            onClick={() =>
              setActivePage("Orders")
            }
            variant={
              activePage === "Orders"
                ? "contained"
                : "text"
            }
            sx={{
              textTransform: "none",
              fontWeight: 700,
            }}
          >
            My Orders
          </Button>

          <Button
            startIcon={<PersonIcon />}
            onClick={() =>
              setActivePage("Profile")
            }
            variant={
              activePage === "Profile"
                ? "contained"
                : "text"
            }
            sx={{
              textTransform: "none",
              fontWeight: 700,
            }}
          >
            Profile
          </Button>
        </Box>
      </Paper>

      {/* CONTENT */}

      <Box
        sx={{
          maxWidth: 1400,
          mx: "auto",
          p: {
            xs: 2,
            md: 4,
          },
        }}
      >
        {activePage === "Home" &&
          renderHome()}

        {activePage === "Orders" &&
          renderOrders()}

        {activePage === "Profile" &&
          renderProfile()}
      </Box>

      {/* CART DRAWER */}

      <Drawer
        anchor="right"
        open={cartOpen}
        onClose={() =>
          setCartOpen(false)
        }
      >
        {cartDrawer}
      </Drawer>
    </Box>
  );
};

export default UserDashboard;
